/**
 * `exertion` follows the advisory's wording ("outdoor physical exertion",
 * "outdoor physical activities"); commuting is exposure without exercise.
 */
export const ACTIVITIES = {
  walking: { label: "Walking", outdoors: true, exertion: "moderate" },
  running: { label: "Running", outdoors: true, exertion: "strenuous" },
  cycling: { label: "Cycling", outdoors: true, exertion: "strenuous" },
  exercise: { label: "Outdoor exercise", outdoors: true, exertion: "strenuous" },
  commuting: { label: "Commuting", outdoors: true, exertion: "none" },
  outdoor: { label: "General outdoor activity", outdoors: true, exertion: "moderate" },
  indoor: { label: "Indoor activity", outdoors: false, exertion: "none" },
} as const;

export type ActivityId = keyof typeof ACTIVITIES;
export const ACTIVITY_IDS = Object.keys(ACTIVITIES) as ActivityId[];

